  async getAllStockModels(): Promise<StockModel[]> {
    // Use pgPool for proper boolean handling - Neon HTTP driver has boolean coercion issues
    const { pgPool } = await import('./db');
    const { rows } = await pgPool.query('SELECT id, name, display_name, price, description, handedness, is_active, sort_order, created_at, updated_at FROM stock_models ORDER BY sort_order');
    return rows.map((row: any) => ({
      id: row.id,
      name: row.name,
      displayName: row.display_name || row.name,
      price: Number(row.price || 0),
      description: row.description,
      handedness: row.handedness,
      isActive: row.is_active === true,
      sortOrder: row.sort_order ?? 0,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    }));
  }

  async getStockModel(id: string): Promise<StockModel | undefined> {
    const [stockModel] = await db
      .select()
      .from(stockModels)
      .where(eq(stockModels.id, id));
    return stockModel || undefined;
  }

  async createStockModel(data: InsertStockModel): Promise<StockModel> {
    // Generate ID from name if not provided
    let baseId = data.id || data.name.toLowerCase().replace(/[^a-z0-9]/g, '_');
    let id = baseId;
    let counter = 1;

    // Check for existing ID and increment if needed
    while (true) {
      try {
        const stockModelData = { ...data, id };
        const [stockModel] = await db
          .insert(stockModels)
          .values(stockModelData)
          .returning();
        return stockModel;
      } catch (error: any) {
        // If duplicate key error, try with incremented suffix
        if (
          error.code === '23505' &&
          error.constraint === 'stock_models_pkey'
        ) {
          counter++;
          id = `${baseId}_${counter}`;
          continue;
        }
        // If it's a different error, throw it
        throw error;
      }
    }
  }

