  // Time Clock CRUD
  async getTimeClockStatus(
    employeeId: string
  ): Promise<{
    status: 'IN' | 'OUT';
    clockIn: string | null;
    clockOut: string | null;
  }> {
    const today = new Date().toISOString().split('T')[0];
    const [entry] = await db
      .select()
      .from(timeClockEntries)
      .where(
        and(
          eq(timeClockEntries.employeeId, employeeId),
          eq(timeClockEntries.date, today)
        )
      )
      .orderBy(desc(timeClockEntries.id))
      .limit(1);

    if (!entry) {
      return { status: 'OUT', clockIn: null, clockOut: null };
    }

    return {
      status: entry.clockOut ? 'OUT' : 'IN',
      clockIn: entry.clockIn?.toISOString() || null,
      clockOut: entry.clockOut?.toISOString() || null,
    };
  }

  async getOpenTimeClockEntry(employeeId: string): Promise<TimeClockEntry | null> {
    const [entry] = await db
      .select()
      .from(timeClockEntries)
      .where(
        and(
          eq(timeClockEntries.employeeId, employeeId),
          isNotNull(timeClockEntries.clockIn),
          isNull(timeClockEntries.clockOut)
        )
      )
      .orderBy(desc(timeClockEntries.clockIn))
      .limit(1);
    return entry ?? null;
  }

  async getTimeClockEntries(
    employeeId?: string,
    date?: string,
    limit: number = DEFAULT_SESSIONS_LIMIT,
    offset: number = 0
  ): Promise<TimeClockEntry[]> {
    let query = db.select().from(timeClockEntries);

    if (employeeId && date) {
      query = query.where(
        and(
          eq(timeClockEntries.employeeId, employeeId),
          eq(timeClockEntries.date, date)
        )
      );
    } else if (employeeId) {
      query = query.where(eq(timeClockEntries.employeeId, employeeId));
    } else if (date) {
      query = query.where(eq(timeClockEntries.date, date));
    }

    return await query.orderBy(desc(timeClockEntries.date)).limit(limit).offset(offset);
  }

  async createTimeClockEntry(
    data: InsertTimeClockEntry
  ): Promise<TimeClockEntry> {
    // Normalize the date to YYYY-MM-DD format
    const normalizedData = {
      ...data,
      date:
        typeof data.date === 'string'
          ? data.date
          : new Date(data.date).toISOString().split('T')[0],
    };
    const [entry] = await db
      .insert(timeClockEntries)
      .values(normalizedData)
      .returning();
    return entry;
  }

  async updateTimeClockEntry(
    id: number,
    data: Partial<InsertTimeClockEntry>
  ): Promise<TimeClockEntry> {
    // Normalize the date to YYYY-MM-DD format if provided
    const normalizedData = data.date
      ? {
          ...data,
          date:
            typeof data.date === 'string'
              ? data.date
              : new Date(data.date).toISOString().split('T')[0],
        }
      : data;

    const [entry] = await db
      .update(timeClockEntries)
      .set(normalizedData)
      .where(eq(timeClockEntries.id, id))
      .returning();
    return entry;
  }

  async deleteTimeClockEntry(id: number): Promise<void> {
    await db.delete(timeClockEntries).where(eq(timeClockEntries.id, id));
  }

