  // Checklist CRUD
  async getChecklistItems(
    employeeId: string,
    date: string
  ): Promise<ChecklistItem[]> {
    const items = await db
      .select()
      .from(checklistItems)
      .where(
        and(
          eq(checklistItems.employeeId, employeeId),
          eq(checklistItems.date, date)
        )
      )
      .orderBy(checklistItems.id);

    // If no items exist for today, create default checklist items
    if (items.length === 0) {
      const defaultItems = [
        {
          employeeId,
          date,
          label: 'Review safety procedures',
          type: 'checkbox' as const,
          required: true,
        },
        {
          employeeId,
          date,
          label: 'Check equipment status',
          type: 'dropdown' as const,
          options: ['Good', 'Needs Attention', 'Broken'],
          required: true,
        },
        {
          employeeId,
          date,
          label: 'Work area cleanliness',
          type: 'dropdown' as const,
          options: ['Clean', 'Needs Cleaning', 'Deep Clean Required'],
          required: true,
        },
        {
          employeeId,
          date,
          label: 'Special notes',
          type: 'text' as const,
          required: false,
        },
      ];

      const createdItems = [];
      for (const item of defaultItems) {
        const [created] = await db
          .insert(checklistItems)
          .values(item)
          .returning();
        createdItems.push(created);
      }
      return createdItems;
    }

    return items;
  }

  async createChecklistItem(data: InsertChecklistItem): Promise<ChecklistItem> {
    // Convert Date objects to strings for date fields
    const insertData: any = { ...data };
    if (insertData.date instanceof Date) {
      insertData.date = insertData.date.toISOString().split('T')[0];
    }

    const [item] = await db
      .insert(checklistItems)
      .values(insertData)
      .returning();
    return item;
  }

