  async createPurchaseOrderItem(
    data: InsertPurchaseOrderItem
  ): Promise<PurchaseOrderItem> {
    console.log('📦 Creating purchase order item with data:', JSON.stringify(data));
    const result = await db.insert(purchaseOrderItems).values(data).returning();
    console.log('📦 Insert result:', JSON.stringify(result));
    if (!result || result.length === 0) {
      throw new Error('Failed to create purchase order item - no result returned from database');
    }
    return formatDates(result[0] as Record<string, unknown>, PURCHASE_ORDER_ITEM_DATE_COLUMNS) as PurchaseOrderItem;
  }

  async updatePurchaseOrderItem(
    id: number,
    data: Partial<InsertPurchaseOrderItem>
  ): Promise<PurchaseOrderItem> {
    const { TransitionValidationError } = await import('./src/services/orderTransitionValidator');

    function isTerminalStockStatus(s: string | null | undefined): boolean {
      return s === 'SHIPPED' || s === 'FULFILLED';
    }

    // Guard: fetch current item to check stock status before any update
    const currentItems = await db
      .select()
      .from(purchaseOrderItems)
      .where(eq(purchaseOrderItems.id, id));

    if (currentItems.length > 0) {
      const current = currentItems[0];

      // Prevent clearing or downgrading a SHIPPED or FULFILLED item's stock status
      if (
        isTerminalStockStatus(current.stockStatus) &&
        'stockStatus' in data &&
        !isTerminalStockStatus(data.stockStatus)
      ) {
        throw new TransitionValidationError(
          'SHIPPED_ITEM_STATUS_DOWNGRADE',
          `PO item ${id} is already ${current.stockStatus} — its stock status cannot be cleared or downgraded.`,
          { itemId: id, currentStatus: current.stockStatus, attemptedStatus: data.stockStatus ?? null }
        );
      }

      // Calculate total price if quantity or unitPrice changed
      if (data.quantity !== undefined || data.unitPrice !== undefined) {
        const quantity = data.quantity ?? current.quantity;
        const unitPrice = data.unitPrice ?? current.unitPrice;
        data.totalPrice = quantity * unitPrice;
      }
    }

    const [item] = await db
      .update(purchaseOrderItems)
      .set(data)
      .where(eq(purchaseOrderItems.id, id))
      .returning();
    return formatDates(item as Record<string, unknown>, PURCHASE_ORDER_ITEM_DATE_COLUMNS) as PurchaseOrderItem;
  }

  async deletePurchaseOrderItem(id: number): Promise<void> {
    await db.delete(purchaseOrderItems).where(eq(purchaseOrderItems.id, id));
  }

  // Production Orders CRUD
  async getAllProductionOrders(): Promise<ProductionOrder[]> {
    const orders = await db
      .select(productionOrdersColumns)
      .from(productionOrders)
      .orderBy(
        asc(productionOrders.dueDate), // Most urgent due dates first
        asc(sql`CASE 
          WHEN ${productionOrders.dueDate} < CURRENT_DATE THEN 1 
          WHEN ${productionOrders.dueDate} <= CURRENT_DATE + INTERVAL '7 days' THEN 10
          WHEN ${productionOrders.dueDate} <= CURRENT_DATE + INTERVAL '30 days' THEN 30
          ELSE 50 
        END`), // Priority score (lower = higher priority)
        desc(productionOrders.createdAt) // Newest first as tie-breaker
      );

    // Build P1 purchase order item lookup: id → itemName
    const p1Items = await db.select({
      id: purchaseOrderItems.id,
      itemName: purchaseOrderItems.itemName,
    }).from(purchaseOrderItems);
    const p1ItemMap = new Map(p1Items.map((i) => [i.id.toString(), i.itemName]));

    // Build P2 purchase order item lookup: id → partName
    const p2Items = await db.select({
      id: p2PurchaseOrderItems.id,
      partName: p2PurchaseOrderItems.partName,
    }).from(p2PurchaseOrderItems);
    const p2ItemMap = new Map(p2Items.map((i) => [i.id.toString(), i.partName]));

    // Resolve itemName: if the stored value is empty or a raw numeric ID, look it up
    return orders.map((order) => {
      const needsResolution = !order.itemName || /^\d+$/.test(order.itemName);
      const resolved = needsResolution
        ? (p2ItemMap.get(order.p2PoItemId?.toString() || '') ||
           p1ItemMap.get(order.poItemId?.toString() || '') ||
           p2ItemMap.get(order.itemId?.toString() || '') ||
           p1ItemMap.get(order.itemId?.toString() || '') ||
           order.itemName)
        : order.itemName;
      return formatDates({ ...order, itemName: resolved } as Record<string, unknown>, PRODUCTION_ORDER_DATE_COLUMNS) as ProductionOrder;
    });
  }

