  async updateP2Customer(
    id: number,
    data: Partial<InsertP2Customer>
  ): Promise<P2Customer | undefined> {
    // Use pg pool instead of Drizzle/Neon HTTP driver for better compatibility
    const setClauses: string[] = [];
    const params: any[] = [];
    
    // Map camelCase to snake_case for database columns
    const columnMap: Record<string, string> = {
      customerName: 'customer_name',
      contactEmail: 'contact_email',
      contactPhone: 'contact_phone',
      billingAddress: 'billing_address',
      billingCity: 'billing_city',
      billingState: 'billing_state',
      billingZip: 'billing_zip',
      shippingCompanyName: 'shipping_company_name',
      shippingContactName: 'shipping_contact_name',
      shippingAddress: 'shipping_address',
      shippingAddress2: 'shipping_address_2',
      shippingCity: 'shipping_city',
      shippingState: 'shipping_state',
      shippingZip: 'shipping_zip',
      shipToAddress: 'ship_to_address',
      paymentTerms: 'payment_terms',
      status: 'status',
      notes: 'notes',
      rfqPrefix: 'rfq_prefix',
      rfqSequences: 'rfq_sequences',
    };
    
    for (const [key, value] of Object.entries(data)) {
      const column = columnMap[key];
      if (column && value !== undefined) {
        params.push(key === 'rfqSequences' ? JSON.stringify(value) : value);
        setClauses.push(`${column} = $${params.length}`);
      }
    }
    
    if (setClauses.length === 0) {
      // No updates to make, just return the existing customer
      const result = await pool.query(`
        SELECT id, customer_id as "customerId", customer_name as "customerName",
          contact_email as "contactEmail", contact_phone as "contactPhone",
          billing_address as "billingAddress", billing_city as "billingCity",
          billing_state as "billingState", billing_zip as "billingZip",
          shipping_company_name as "shippingCompanyName", shipping_contact_name as "shippingContactName",
          shipping_address as "shippingAddress", shipping_address_2 as "shippingAddress2",
          shipping_city as "shippingCity", shipping_state as "shippingState", shipping_zip as "shippingZip",
          ship_to_address as "shipToAddress", payment_terms as "paymentTerms",
          status, notes, rfq_prefix as "rfqPrefix", rfq_sequences as "rfqSequences",
          created_at as "createdAt", updated_at as "updatedAt"
        FROM p2_customers WHERE id = $1
      `, [id]);
      return result.rows[0] as P2Customer | undefined;
    }
    
    // Add updated_at
    setClauses.push(`updated_at = NOW()`);
    params.push(id);
    
    const result = await pool.query(`
      UPDATE p2_customers 
      SET ${setClauses.join(', ')}
      WHERE id = $${params.length}
      RETURNING id, customer_id as "customerId", customer_name as "customerName",
        contact_email as "contactEmail", contact_phone as "contactPhone",
        billing_address as "billingAddress", billing_city as "billingCity",
        billing_state as "billingState", billing_zip as "billingZip",
        shipping_company_name as "shippingCompanyName", shipping_contact_name as "shippingContactName",
        shipping_address as "shippingAddress", shipping_address_2 as "shippingAddress2",
        shipping_city as "shippingCity", shipping_state as "shippingState", shipping_zip as "shippingZip",
        ship_to_address as "shipToAddress", payment_terms as "paymentTerms",
        status, notes, rfq_prefix as "rfqPrefix", rfq_sequences as "rfqSequences",
        created_at as "createdAt", updated_at as "updatedAt"
    `, params);
    
    return result.rows[0] as P2Customer | undefined;
  }

