  async createP2PurchaseOrderItem(
    data: InsertP2PurchaseOrderItem
  ): Promise<P2PurchaseOrderItem> {
    // Calculate totalPrice from quantity and unitPrice
    const totalPrice = data.quantity * (data.unitPrice || 0);
    
    const [item] = await db
      .insert(p2PurchaseOrderItems)
      .values({ ...data, totalPrice })
      .returning();

    // Auto-assign inventoryItemId if not provided — look up by agPartNumber matching partNumber
    if (!item.inventoryItemId && item.partNumber) {
      try {
        const { eq } = await import('drizzle-orm');
        const [matchedInvItem] = await db
          .select({ id: inventoryItems.id })
          .from(inventoryItems)
          .where(eq(inventoryItems.agPartNumber, item.partNumber))
          .limit(1);
        if (matchedInvItem) {
          await db
            .update(p2PurchaseOrderItems)
            .set({ inventoryItemId: matchedInvItem.id })
            .where(eq(p2PurchaseOrderItems.id, item.id));
          item.inventoryItemId = matchedInvItem.id;
        }
      } catch (invLookupErr) {
        console.warn('⚠️ Auto-assign inventoryItemId failed for PO item:', invLookupErr);
      }
    }

    // Reopen a CLOSED P2 PO when a new item is added
    try {
      const parentPO = await this.getP2PurchaseOrder(item.poId);
      if (parentPO && parentPO.status === 'CLOSED') {
        await this.updateP2PurchaseOrder(item.poId, { status: 'OPEN' });
      }
    } catch (error) {
      console.error('Error reopening closed P2 PO:', error);
      // Don't fail PO item creation if status update fails
    }

    try {
      // Get the P2 PO to extract due date
      const p2Po = await this.getP2PurchaseOrder(item.poId);
      const dueDate = p2Po?.expectedDelivery ? new Date(p2Po.expectedDelivery) : null;

      // Step 1: Check if this part itself is manufactured (direct)
      const { autoPopulateManufacturingQueue } = await import('./src/utils/manufacturingQueueHelper');
      await autoPopulateManufacturingQueue({
        inventoryPartNumber: item.partNumber,
        quantity: item.quantity,
        p2PoId: item.poId,
        p2PoItemId: item.id,
        dueDate,
      });

      // Step 2: BOM Explosion - Check if this part has a BOM with manufactured components
      const { explodeBOMForManufacturing } = await import('./src/utils/manufacturingQueueHelper');
      await explodeBOMForManufacturing({
        partNumber: item.partNumber,
        quantity: item.quantity,
        p2PoId: item.poId,
        p2PoItemId: item.id,
        dueDate,
      });
    } catch (error) {
      console.error('Error auto-populating manufacturing queue for P2 PO item:', error);
      // Don't fail PO item creation if queue population fails
    }

    return item;
  }

  async updateP2PurchaseOrderItem(
    id: number,
    data: Partial<InsertP2PurchaseOrderItem>
  ): Promise<P2PurchaseOrderItem> {
    // Calculate total price if quantity or unitPrice changed
    if (data.quantity !== undefined || data.unitPrice !== undefined) {
      const currentItem = await db
        .select()
        .from(p2PurchaseOrderItems)
        .where(eq(p2PurchaseOrderItems.id, id));
      if (currentItem.length > 0) {
        const item = currentItem[0];
        const quantity = data.quantity ?? item.quantity;
        const unitPrice = data.unitPrice ?? item.unitPrice;
        data.totalPrice = quantity * unitPrice;
      }
    }

    const [item] = await db
      .update(p2PurchaseOrderItems)
      .set(data)
      .where(eq(p2PurchaseOrderItems.id, id))
      .returning();
    return item;
  }

  async deleteP2PurchaseOrderItem(id: number): Promise<void> {
    await db
      .delete(p2PurchaseOrderItems)
      .where(eq(p2PurchaseOrderItems.id, id));
  }

