  async switchActiveTimeEntryToTraveler(params: {
    employeeId: string;
    productionWorkOrderId: string | null;
    travelerId: string | null;
    chargeCode: string | null;
    department: string | null;
    operation: string | null;
    laborApprovalId?: number | null;
    laborBudgetOverrideId?: number | null;
  }): Promise<{ closed: TimeClockEntry | null; created: TimeClockEntry }> {
    const now = new Date();
    const today = now.toISOString().split('T')[0];

    return await db.transaction(async (tx) => {
      const [activeEntry] = await tx
        .select()
        .from(timeClockEntries)
        .where(
          and(
            eq(timeClockEntries.employeeId, params.employeeId),
            isNotNull(timeClockEntries.clockIn),
            isNull(timeClockEntries.clockOut)
          )
        )
        .orderBy(desc(timeClockEntries.clockIn))
        .limit(1);

      let closed: TimeClockEntry | null = null;
      if (activeEntry) {
        const [closedEntry] = await tx
          .update(timeClockEntries)
          .set({ clockOut: now })
          .where(eq(timeClockEntries.id, activeEntry.id))
          .returning();
        closed = closedEntry;
      }

      const normalizedDate = today;
      const [created] = await tx
        .insert(timeClockEntries)
        .values({
          employeeId: params.employeeId,
          date: normalizedDate,
          clockIn: now,
          clockOut: null,
          productionWorkOrderId: params.productionWorkOrderId,
          travelerId: params.travelerId,
          chargeCode: params.chargeCode,
          department: params.department,
          operation: params.operation,
          // §5.2 (Task #77): legacy time_clock_entries duplicate-write path. Traveler-driven
          // sessions enter PENDING_APPROVAL here as well unless an explicit override/approval
          // id was already validated upstream (APPROVED_OVERRUN).
          approvalStatus: (params.laborApprovalId != null || params.laborBudgetOverrideId != null) ? 'APPROVED_OVERRUN' : 'PENDING_APPROVAL',
          laborApprovalId: params.laborApprovalId ?? null,
          laborBudgetOverrideId: params.laborBudgetOverrideId ?? null,
        })
        .returning();

      return { closed, created };
    });
  }

  async getLaborHoursByWorkOrder(workOrderId: string): Promise<number> {
    // Task #1186: Read from punch_ledger (unified source of truth)
    const result = await db.execute(
      sql`SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(clock_out, NOW()) - clock_in)) / 3600.0), 0) AS total_hours
          FROM punch_ledger
          WHERE production_work_order_id = ${workOrderId}::uuid
            AND labor_class = 'REGULAR'`
    );
    const rows = Array.isArray(result) ? result : (result?.rows ?? []);
    return parseFloat(rows[0]?.total_hours ?? '0');
  }

  async getLaborHoursByWorkOrderAndDepartment(workOrderId: string, department: string): Promise<number> {
    // Task #1186: Read from punch_ledger (unified source of truth)
    const result = await db.execute(
      sql`SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(clock_out, NOW()) - clock_in)) / 3600.0), 0) AS total_hours
          FROM punch_ledger
          WHERE production_work_order_id = ${workOrderId}::uuid
            AND department = ${department}
            AND labor_class = 'REGULAR'`
    );
    const rows = Array.isArray(result) ? result : (result?.rows ?? []);
    return parseFloat(rows[0]?.total_hours ?? '0');
  }

