  // Update finalized order
  async updateFinalizedOrder(
    orderId: string,
    data: Partial<InsertAllOrder>
  ): Promise<AllOrder> {
    try {
      const updateData: Partial<InsertAllOrder> = { ...data };
      if (Object.prototype.hasOwnProperty.call(updateData, 'dueDate')) {
        delete updateData.dueDate;
      }

      console.log(`[updateFinalizedOrder] Updating order ${orderId} with keys:`, Object.keys(updateData));

      // Check upfront whether a production_orders record exists so we can sync it atomically.
      const productionRecord =
        updateData.currentDepartment !== undefined
          ? await this.getProductionOrderByOrderId(orderId)
          : undefined;

      const order = await db.transaction(async (tx) => {
        if (Object.keys(updateData).length > 0) {
          await tx
            .update(allOrders)
            .set({ ...updateData, updatedAt: new Date() })
            .where(eq(allOrders.orderId, orderId));
        }

        const [updated] = await tx
          .select()
          .from(allOrders)
          .where(eq(allOrders.orderId, orderId))
          .limit(1);

        if (!updated) {
          throw new Error(`Finalized order with ID ${orderId} not found`);
        }

        // If currentDepartment is being updated and a production_orders record exists,
        // sync it within the same transaction so getAllOrders deduplication
        // (which prefers production_orders) always returns the correct department.
        if (updateData.currentDepartment !== undefined && productionRecord) {
          await tx.execute(
            sql`UPDATE production_orders SET current_department = ${updateData.currentDepartment}, updated_at = NOW() WHERE order_id = ${orderId}`
          );
          console.log(`[updateFinalizedOrder] Synced production_orders.current_department for ${orderId} → ${updateData.currentDepartment}`);
        }

        return updated;
      });

      return order;
    } catch (err: any) {
      console.error(`[updateFinalizedOrder] Error for ${orderId}:`, err.message);
      throw err;
    }
  }

  async fulfillOrder(orderId: string, actor?: { actorId?: number | null; actorDisplayName?: string | null }): Promise<AllOrder> {
    // Execute update + audit event insert in a single transaction so that if
    // the event write fails, the status change rolls back — no silent bypass.
    const order = await db.transaction(async (tx) => {
      // Capture before state for the audit event
      const [before] = await tx
        .select()
        .from(allOrders)
        .where(eq(allOrders.orderId, orderId))
        .limit(1);

      if (!before) {
        throw new Error(`Order with ID ${orderId} not found`);
      }

      const now = new Date();

      const [after] = await tx
        .update(allOrders)
        .set({
          currentDepartment: 'Shipping Management',
          status: 'FULFILLED',
          shippedDate: now,
          updatedAt: now,
        })
        .where(eq(allOrders.orderId, orderId))
        .returning();

      if (!after) {
        throw new Error(`Failed to fulfill order ${orderId}`);
      }

      // Write canonical audit event atomically with the status update
      await tx.insert(orderActivityEvents).values({
        orderId,
        eventType: 'FULFILL_ORDER',
        eventCategory: 'production',
        occurredAt: now,
        actorId: actor?.actorId ?? null,
        actorType: 'system',
        actorDisplayName: actor?.actorDisplayName ?? null,
        source: 'fulfill-route',
        sourceRoute: '/api/orders/fulfill',
        statusFrom: before.status ?? null,
        statusTo: 'FULFILLED',
        departmentFrom: before.currentDepartment ?? null,
        departmentTo: 'Shipping Management',
        beforeSnapshot: before as InsertOrderActivityEvent['beforeSnapshot'],
        afterSnapshot: after as InsertOrderActivityEvent['afterSnapshot'],
        fieldDiff: {
          status: { before: before.status, after: 'FULFILLED', label: 'Order Status' },
          currentDepartment: { before: before.currentDepartment, after: 'Shipping Management', label: 'Current Department' },
        } as InsertOrderActivityEvent['fieldDiff'],
      } satisfies InsertOrderActivityEvent);

      return after;
    });

    console.log(
      `✅ FULFILLED: Order ${orderId} has been marked as fulfilled and moved to shipping management with shipped date: ${new Date().toISOString()}`
    );
    return order;
  }

  // Sync verification status between draft and finalized orders
  async syncVerificationStatus(): Promise<{
    updatedOrders: number;
    message: string;
  }> {
    console.log(
      '🔄 Starting verification status sync between draft and finalized orders...'
    );

    try {
      // Get mismatched records first
      const mismatches = await db.execute(sql`
        SELECT d.order_id, d.is_verified as draft_verified, a.is_verified as finalized_verified
        FROM order_drafts d 
        JOIN all_orders a ON d.order_id = a.order_id 
        WHERE d.is_verified != a.is_verified
      `);

      if (mismatches.rows.length === 0) {
        return {
          updatedOrders: 0,
          message: 'No verification status mismatches found',
        };
      }

      // Update finalized orders to match drafts — per-order so each change is audited
      const { auditUpdateOrders } = await import('./src/services/orderAuditWrapper');
      let syncedCount = 0;
      for (const row of mismatches.rows as any[]) {
        await auditUpdateOrders({
          db: pool,
          orderIds: [row.order_id],
          changes: { is_verified: row.draft_verified },
          source: 'SYNC_VERIFICATION',
          user: null,
          reason: 'Auto-sync verification status from drafts',
          ip: null,
          userAgent: null,
        });
        syncedCount++;
      }

      console.log(
        `✅ Verification sync complete: ${syncedCount} orders updated`
      );

      return {
        updatedOrders: syncedCount,
        message: `Synced verification status for ${syncedCount} orders`,
      };
    } catch (error) {
      console.error('❌ Error syncing verification status:', error);
      throw new Error(
        `Failed to sync verification status: ${(error as Error).message}`
      );
    }
  }

