  async getMetalAccessoriesDemands(): Promise<any[]> {
    const items = await this.getAllMetalAccessories();

    const ordersFinalized = await db
      .select()
      .from(allOrders)
      .where(
        and(
          eq(allOrders.status, 'FINALIZED'),
          eq(allOrders.isCancelled, false)
        )
      );

    // Also get PO items with custom_model type (metal accessories from POs)
    // These are items that bypass production and need to be tracked as demand
    const poMetalAccessories = await db.execute(sql`
      SELECT 
        poi.id as "poItemId",
        poi.item_name as "itemName",
        poi.stock_model_name as "stockModelName",
        poi.quantity,
        poi.due_date as "dueDate",
        poi.stock_status as "stockStatus",
        po.customer_id as "customerId",
        po.po_number as "poNumber"
      FROM purchase_order_items poi
      JOIN purchase_orders po ON poi.po_id = po.id
      WHERE po.status = 'OPEN'
        AND poi.item_type = 'custom_model'
        AND (poi.stock_status IS NULL OR poi.stock_status != 'SHIPPED')
    `);

    console.log(
      '🔍 Metal Accessories Demands - Total FINALIZED orders:',
      ordersFinalized.length,
      'PO metal accessories:',
      poMetalAccessories.rows?.length || 0
    );

    const demands = items.map((item) => {
      const weeklyDemand = [0, 0, 0, 0];
      const weeklyOrders: any[][] = [[], [], [], []]; // Track orders for each week
      const now = new Date();

      // Normalize item name for comparison (remove hyphens/underscores, lowercase)
      const normalizedItemName = item.name.toLowerCase().replace(/[-_]/g, '');

      ordersFinalized.forEach((order) => {
        const features = order.features as any;
        const featureQuantities = order.featureQuantities as any;

        let matchFound = false;
        let quantity = 0;

        // Special logic for Cheek Riser items - check for "Adj" in model ID
        if (
          item.name === 'Cheek Riser - Stock Inserts' ||
          item.name === 'Cheek Riser - Riser Inserts'
        ) {
          if (order.modelId && order.modelId.toLowerCase().includes('adj')) {
            quantity = 1; // Each order with adjustable stock needs these inserts
            matchFound = true;
          }
        } else {
          // Check featureQuantities for accessories with quantities
          if (featureQuantities && typeof featureQuantities === 'object') {
            Object.keys(featureQuantities).forEach((featureKey) => {
              const normalizedKey = featureKey
                .toLowerCase()
                .replace(/[-_]/g, '');
              if (normalizedKey.includes(normalizedItemName)) {
                quantity = parseInt(featureQuantities[featureKey]) || 0;
                if (quantity > 0) {
                  matchFound = true;
                }
              }
            });
          }

          // Check features.bottom_metal for bottom metal selections
          if (!matchFound && features && features.bottom_metal) {
            const normalizedBottomMetal = features.bottom_metal
              .toLowerCase()
              .replace(/[-_]/g, '');
            if (normalizedBottomMetal === normalizedItemName) {
              quantity = 1; // Each order needs 1 bottom metal
              matchFound = true;
            }
          }
        }

        // If match found, add to weekly demand
        if (matchFound && quantity > 0) {
          const dueDate = order.dueDate ? new Date(order.dueDate) : null;

          if (dueDate) {
            const daysUntilDue = Math.ceil(
              (dueDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)
            );
            const weekIndex = Math.min(
              Math.max(Math.floor(daysUntilDue / 7), 0),
              3
            );

            weeklyDemand[weekIndex] += quantity;
            weeklyOrders[weekIndex].push({
              orderId: order.orderId,
              dueDate: order.dueDate,
              quantity,
              customerId: order.customerId,
              status: order.status,
            });
          } else {
            weeklyDemand[0] += quantity;
            weeklyOrders[0].push({
              orderId: order.orderId,
              dueDate: order.dueDate,
              quantity,
              customerId: order.customerId,
              status: order.status,
            });
          }
        }
      });

      // Also check PO metal accessories (custom_model items)
      const poRows = poMetalAccessories.rows || [];
      poRows.forEach((poItem: any) => {
        // Skip if already matched to prevent double-counting
        const poItemId = poItem.poItemId;
        
        // Normalize to canonical SKU - remove known prefixes to get core identifier
        // AG-M5-LA should match AG-BM-M5-LA (both normalize to M5LA)
        const normalizeToCanonical = (name: string): string => {
          if (!name || name.length < 3) return '';
          return name.toUpperCase()
            .replace(/^AG-?/i, '')     // Remove AG- or AG prefix
            .replace(/^BM-?/i, '')     // Remove BM- or BM prefix  
            .replace(/[-_\s]/g, '');   // Remove separators
        };
        
        const canonicalItemName = normalizeToCanonical(item.name);
        const rawPoName = poItem.itemName || poItem.stockModelName || '';
        const canonicalPoName = normalizeToCanonical(rawPoName);
        
        // Skip empty or too short names
        if (!canonicalItemName || canonicalItemName.length < 3 || !canonicalPoName || canonicalPoName.length < 3) {
          return;
        }
        
        // Exact canonical match only - no fuzzy matching to prevent false positives
        // M5LA matches M5LA, M5BDLLA matches M5BDLLA, etc.
        const match = canonicalItemName === canonicalPoName;
        
        if (match) {
          const quantity = poItem.quantity || 1;
          const dueDate = poItem.dueDate ? new Date(poItem.dueDate) : null;
          const now = new Date();
          
          if (dueDate) {
            const daysUntilDue = Math.ceil(
              (dueDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)
            );
            const weekIndex = Math.min(
              Math.max(Math.floor(daysUntilDue / 7), 0),
              3
            );

            weeklyDemand[weekIndex] += quantity;
            weeklyOrders[weekIndex].push({
              orderId: `PO-${poItem.poNumber}`,
              dueDate: poItem.dueDate,
              quantity,
              customerId: poItem.customerId,
              status: 'PO_ITEM',
              poItemId: poItem.poItemId,
            });
          } else {
            // No due date - add to first week
            weeklyDemand[0] += quantity;
            weeklyOrders[0].push({
              orderId: `PO-${poItem.poNumber}`,
              dueDate: null,
              quantity,
              customerId: poItem.customerId,
              status: 'PO_ITEM',
              poItemId: poItem.poItemId,
            });
          }
        }
      });

      const totalDemandNext4 = weeklyDemand.reduce((a, b) => a + b, 0);
      const available = item.inventory + item.machined + item.atAnodizer;
      // Account for minimum threshold: we need enough to cover demand AND maintain threshold
      const totalNeeded = totalDemandNext4 + (item.minimumThreshold || 0);
      const need = totalNeeded - available;

      return {
        itemId: item.id,
        name: item.name,
        category: item.category,
        inventory: item.inventory,
        minimumThreshold: item.minimumThreshold || 0,
        machined: item.machined,
        atAnodizer: item.atAnodizer,
        weeklyDemand,
        weeklyOrders, // Include order details for each week
        totalDemandNext4,
        productionNeeded: need > 0 ? need : 0,
      };
    });

    return demands;
  }

