  async checkWorkOrderMaterialAvailability(workOrderId: string): Promise<boolean> {
    const [wad] = await db
      .select({
        partNumber: productionWorkOrders.partNumber,
        quantity: productionWorkOrders.quantity,
      })
      .from(productionWorkOrders)
      .where(eq(productionWorkOrders.id, workOrderId))
      .limit(1);
    if (!wad || !wad.partNumber) return true;

    const [bom] = await db
      .select()
      .from(boms)
      .where(and(eq(boms.parentPartAgNumber, wad.partNumber), eq(boms.isActive, true)))
      .limit(1);
    if (!bom) return true;

    const [revision] = await db
      .select()
      .from(bomRevisions)
      .where(and(eq(bomRevisions.bomId, bom.id), eq(bomRevisions.isReleased, true)))
      .orderBy(desc(bomRevisions.createdAt))
      .limit(1);
    if (!revision) return true;

    const lines = await db
      .select()
      .from(bomLines)
      .where(eq(bomLines.revisionId, revision.id));
    if (!lines.length) return true;

    const required = wad.quantity ?? 1;
    for (const line of lines) {
      const qtyPer = Number(line.qtyPer ?? 1);
      const needed = qtyPer * required;
      const [balance] = await db
        .select({ quantityAvailable: inventoryBalances.quantityAvailable })
        .from(inventoryBalances)
        .where(eq(inventoryBalances.agPartNumber, line.childPartAgNumber))
        .limit(1);
      const available = balance ? Number(balance.quantityAvailable ?? 0) : 0;
      if (available < needed) return false;
    }
    return true;
  }

  async getMaterialShortageDetail(workOrderId: string): Promise<string | null> {
    const [wad] = await db
      .select({
        partNumber: productionWorkOrders.partNumber,
        quantity: productionWorkOrders.quantity,
      })
      .from(productionWorkOrders)
      .where(eq(productionWorkOrders.id, workOrderId))
      .limit(1);
    if (!wad || !wad.partNumber) return null;

    const [bom] = await db
      .select()
      .from(boms)
      .where(and(eq(boms.parentPartAgNumber, wad.partNumber), eq(boms.isActive, true)))
      .limit(1);
    if (!bom) return null;

    const [revision] = await db
      .select()
      .from(bomRevisions)
      .where(and(eq(bomRevisions.bomId, bom.id), eq(bomRevisions.isReleased, true)))
      .orderBy(desc(bomRevisions.createdAt))
      .limit(1);
    if (!revision) return null;

    const lines = await db
      .select()
      .from(bomLines)
      .where(eq(bomLines.revisionId, revision.id));

    const required = wad.quantity ?? 1;
    for (const line of lines) {
      const qtyPer = Number(line.qtyPer ?? 1);
      const needed = qtyPer * required;
      const [balance] = await db
        .select({ quantityAvailable: inventoryBalances.quantityAvailable })
        .from(inventoryBalances)
        .where(eq(inventoryBalances.agPartNumber, line.childPartAgNumber))
        .limit(1);
      const available = balance ? Number(balance.quantityAvailable ?? 0) : 0;
      if (available < needed) return line.childPartAgNumber;
    }
    return null;
  }

  async checkWorkOrderTrainingCoverage(workOrderId: string): Promise<boolean> {
    const [wad] = await db
      .select({ partNumber: productionWorkOrders.partNumber })
      .from(productionWorkOrders)
      .where(eq(productionWorkOrders.id, workOrderId))
      .limit(1);
    if (!wad || !wad.partNumber) return true;

    const routing = await db.query.partRoutings.findFirst({
      where: and(
        eq(partRoutings.partNumber, wad.partNumber),
        eq(partRoutings.isActive, true)
      ),
    });
    if (!routing) return true;

    // Fetch all operations that require certification for this routing
    const certOps = await db
      .select({
        certificationId: routingOperations.certificationId,
        operationName: routingOperations.operationName,
      })
      .from(routingOperations)
      .where(and(
        eq(routingOperations.partRoutingId, routing.id),
        eq(routingOperations.requiresCertification, true)
      ));

    if (certOps.length === 0) return true;

    // Any operation marked as requiring certification but with no specific cert
    // assigned is an unmapped gap — block until it is resolved
    const unmapped = certOps.find((op) => op.certificationId === null);
    if (unmapped) return false;

    // Collect unique certification IDs required across all operations
    const requiredCertIds = [...new Set(certOps.map((op) => op.certificationId as number))];

    // For each required certification, confirm at least one active employee holds
    // an active, non-expired record for it. employee_certifications is not in the
    // Drizzle ORM schema so we query via raw SQL; join employees to ensure the
    // employee themselves is still active (not terminated/inactive).
    for (const certId of requiredCertIds) {
      const covered = await db.execute(
        sql`SELECT ec.id
            FROM employee_certifications ec
            JOIN employees e ON e.id = ec.employee_id
            WHERE ec.certification_id = ${certId}
              AND ec.is_active = true
              AND (ec.expiry_date IS NULL OR ec.expiry_date >= CURRENT_DATE)
              AND e.is_active = true
            LIMIT 1`
      );
      if ((covered.rows ?? []).length === 0) {
        return false;
      }
    }

    return true;
  }

